-- ═══════════════════════════════════════════════════════════════
-- 单元1 文字处理(Word) > 任务1 录入和编辑文档 (1166-1175)
-- ═══════════════════════════════════════════════════════════════

UPDATE knowledge_nodes SET content = '## Word 2010 工作界面\n\n| 区域 | 说明 |\n|------|------|\n| 标题栏 | 显示文档名称+程序名，右侧最小化/最大化/关闭按钮 |\n| 快速访问工具栏 | 常用命令（保存/撤消/恢复），可自定义添加 |\n| 功能区（Ribbon） | 选项卡→组→命令按钮的三级结构。常用选项卡：开始/插入/页面布局/引用/邮件/审阅/视图 |\n| 标尺 | 水平标尺和垂直标尺，用于设置缩进和页边距 |\n| 编辑区 | 白色区域，输入和编辑文档内容 |\n| 状态栏 | 底部，显示页码/字数/语言/插入/改写状态 |\n| 视图切换按钮 | 右下角，5种视图模式切换\n\n> 考试注意区分"功能区"和"工具栏"：Office 2010使用功能区，Office 2003使用工具栏。' WHERE id = 1166;

UPDATE knowledge_nodes SET content = '## Word 文档视图（5种）\n\n| 视图 | 特点 | 用途 |\n|------|------|------|\n| **页面视图** | 所见即所得，显示实际打印效果 | 日常编辑排版（默认） |\n| **阅读版式视图** | 模拟翻书效果，隐藏功能区 | 阅读长文档 |\n| **Web版式视图** | 模拟网页显示效果，无分页 | 查看将发布为网页的文档 |\n| **大纲视图** | 按标题层级显示文档结构 | 长文档结构整理、章节调整 |\n| **草稿视图** | 仅显示文字内容，不显示页眉页脚/图片 | 快速录入文字 |\n\n> 考点：能区分5种视图的适用场景。最常用的是页面视图。' WHERE id = 1167;

UPDATE knowledge_nodes SET content = '## 文档基本操作与快捷键\n\n| 操作 | 快捷键 | 说明 |\n|------|------|------|\n| 新建 | Ctrl+N | 创建空白文档 |\n| 打开 | Ctrl+O | 打开已有文档 |\n| 保存 | Ctrl+S | 保存当前文档（首次弹出另存为） |\n| 另存为 | F12 | 以新文件名/位置/格式保存 |\n| 关闭 | Ctrl+W | 关闭当前文档（非退出程序） |\n\n### 保存格式\n| 扩展名 | 说明 |\n|------|------|\n| .docx | Word 2007+ 默认格式 |\n| .doc | Word 97-2003 兼容格式 |\n| .pdf | 固定版式，不可编辑 |\n| .txt | 纯文本，无格式 |\n\n> 考点：Ctrl+S保存、F12另存为。.docx是新版默认格式。' WHERE id = 1168;

UPDATE knowledge_nodes SET content = '## 文档保护\n\nWord提供三种保护方式：\n\n| 保护方式 | 说明 |\n|------|------|\n| **打开密码** | 需要密码才能打开文档 |\n| **修改密码** | 可打开查看，修改需输入密码 |\n| **限制编辑** | 允许特定类型的编辑（如仅允许批注/修订） |\n\n设置路径：文件→信息→保护文档\n\n> 考点：区分"打开密码"和"修改密码"的不同效果。' WHERE id = 1169;

UPDATE knowledge_nodes SET content = '## 打印设置\n\n### 打印预览\n在打印前查看文档的打印效果，避免浪费纸张。\n\n### 打印参数设置\n| 参数 | 说明 |\n|------|------|\n| 打印机选择 | 选择要使用的打印机 |\n| 页码范围 | 全部/当前页/自定义页码范围（如1-5,8,10） |\n| 份数 | 打印份数，支持逐份打印 |\n| 单双面 | 单面/双面（需打印机支持） |\n| 页面方向 | 纵向/横向 |\n| 纸张大小 | A4/A3/B5等 |\n\n快捷操作：Ctrl+P 打开打印面板。' WHERE id = 1170;

UPDATE knowledge_nodes SET content = '## 光标定位与文本选择\n\n### 光标定位快捷键\n| 快捷键 | 功能 |\n|------|------|\n| Home | 移到行首 |\n| End | 移到行尾 |\n| Ctrl+Home | 移到文档开头 |\n| Ctrl+End | 移到文档末尾 |\n| PageUp/PageDown | 上/下翻一屏 |\n\n### 文本选择方法\n| 操作 | 选择范围 |\n|------|------|\n| 双击 | 一个词 |\n| 三击 | 一个段落 |\n| Ctrl+A | 全文 |\n| 单击行左空白处 | 整行 |\n| Shift+方向键 | 扩展选择 |\n| Ctrl+单击 | 选择不连续区域 |\n\n> 考试常考Home/End和Ctrl+Home/Ctrl+End的区别。' WHERE id = 1171;

UPDATE knowledge_nodes SET content = '## 文本编辑操作\n\n### 插入与改写\n- **插入模式**（默认）：输入文字时，光标后文字后移\n- **改写模式**：输入文字时，覆盖光标后文字\n- 按 **Insert** 键切换两种模式（状态栏显示）\n\n### 移动与复制\n| 操作 | 快捷键 | 说明 |\n|------|------|------|\n| 剪切（移动） | Ctrl+X | 删除原文→放入剪贴板→粘贴到新位置 |\n| 复制 | Ctrl+C | 保留原文→复制到剪贴板→粘贴 |\n| 粘贴 | Ctrl+V | 将剪贴板内容粘贴到光标位置 |\n\n### 删除\n| 按键 | 效果 |\n|------|------|\n| Backspace（退格键） | 删除光标**前**的字符 |\n| Delete | 删除光标**后**的字符 |\n\n> 必考：Backspace删前、Delete删后，Insert切换插入/改写。' WHERE id = 1172;

UPDATE knowledge_nodes SET content = '## 查找与替换\n\n### 基本功能\n- **查找**：Ctrl+F，在文档中定位特定文字\n- **替换**：Ctrl+H，查找并替换为指定内容\n\n### 高级替换功能\n| 功能 | 说明 | 示例 |\n|------|------|------|\n| 格式替换 | 将文字替换为带格式的文字 | 将"计算机"替换为**红色加粗**的"计算机" |\n| 特殊格式替换 | 替换段落标记/手动换行符/制表符等 | 将手动换行符替换为段落标记 |\n| 使用通配符 | *匹配任意字符，?匹配单个字符 | "计*机"→匹配"计算机""计算器机" |\n\n> 实操重点：批量格式替换——将文档中所有"计算机"改为红色加粗。' WHERE id = 1173;

UPDATE knowledge_nodes SET content = '## 撤消与恢复\n\n| 操作 | 快捷键 | 说明 |\n|------|------|------|\n| 撤消 | Ctrl+Z | 撤销上一步操作，可连续撤消多步 |\n| 恢复 | Ctrl+Y | 恢复被撤消的操作 |\n\n- Word会记录操作历史，默认可撤消最近100步\n- 快速访问工具栏有撤消/恢复按钮及下拉历史列表\n\n> 这两个快捷键在Office全系通用，必须记住。' WHERE id = 1174;

UPDATE knowledge_nodes SET content = '## 插入特殊元素\n\n### 特殊符号\n插入→符号→选择特殊字符（如©®™→←↑↓等）或数学符号\n\n### 日期和时间\n插入→日期和时间→选择格式→可勾选"自动更新"（每次打开文档时间为当前时间）\n\n### 页码\n插入→页码→选择位置（页面顶端/底端）和对齐方式\n\n### 注意事项\n- 日期勾选"自动更新"后，文档打开时显示当前日期（适合模板）\n- 不勾选则保持插入时的日期不变' WHERE id = 1175;

-- ═══════════════════════════════════════════════════════════════
-- 单元1 > 任务2 设置文档格式 (1176-1185)
-- ═══════════════════════════════════════════════════════════════

UPDATE knowledge_nodes SET content = '## 字符格式\n\n### 字体设置\n| 属性 | 说明 | 中文常用 | 英文常用 |\n|------|------|------|------|\n| 字体 | 文字的书写体 | 宋体/黑体/楷体/仿宋 | Times New Roman/Arial |\n| 字号 | 文字大小 | 五号/小四/四号/三号（号数越小字越大） | 12pt/14pt |\n| 字形 | B加粗(Ctrl+B)/I倾斜(Ctrl+I)/U下划线(Ctrl+U) |\n| 字体颜色 | 更改文字颜色 |\n| 字符间距 | 加宽/紧缩字符之间的距离 |\n| 文字效果 | 阴影/发光/映像等特殊效果（Word 2010新功能） |\n\n> 中文字号"号数越小字越大"，如三号>四号>小四>五号。' WHERE id = 1176;

UPDATE knowledge_nodes SET content = '## 段落格式\n\n### 对齐方式\n| 对齐 | 快捷键 | 说明 |\n|------|------|------|\n| 左对齐 | Ctrl+L | 段落靠左对齐（默认） |\n| 居中 | **Ctrl+E** | 段落居中 |\n| 右对齐 | Ctrl+R | 段落靠右对齐 |\n| 两端对齐 | **Ctrl+J** | 左右两端对齐（中文排版最常用） |\n\n### 缩进\n| 类型 | 说明 |\n|------|------|\n| 首行缩进 | 段落第一行缩进（中文常用2字符） |\n| 悬挂缩进 | 除第一行外其余行缩进 |\n| 左右缩进 | 整段左右同时缩进 |\n\n### 间距\n| 类型 | 说明 |\n|------|------|\n| 段前间距 | 段落上方空出的距离 |\n| 段后间距 | 段落下方空出的距离 |\n| 行距 | 同一段落内行与行之间的距离（单倍/1.5倍/2倍/固定值） |\n\n> 实操重点：段落首行缩进2字符、1.5倍行距是中文公文标准格式。' WHERE id = 1177;

UPDATE knowledge_nodes SET content = '## 项目符号/编号/多级列表\n\n### 项目符号（无序列表）\n- 每项前显示相同的符号（●/○/■/✓等）\n- 适用于并列关系的内容\n\n### 编号列表（有序列表）\n- 每项前自动生成递增序号（1. 2. 3. 或 a) b) c) 等）\n- 适用于有先后顺序的内容\n\n### 多级列表\n- 最多9级嵌套编号\n- 适用于章节结构（如1 → 1.1 → 1.1.1）\n- 与标题样式配合可自动编号\n\n> 实操：选中文字→开始→段落组→选择项目符号/编号样式。' WHERE id = 1178;

UPDATE knowledge_nodes SET content = '## 格式刷\n\n格式刷用于**快速复制格式**（字体/字号/颜色/段落格式等），避免重复设置。\n\n| 操作 | 效果 |\n|------|------|\n| **单击格式刷** | 复制格式后，只能使用一次 |\n| **双击格式刷** | 复制格式后，可多次使用（按Esc退出） |\n\n使用步骤：\n1. 选中已有格式的文字\n2. 单击（或双击）格式刷按钮\n3. 鼠标指针变为刷子形状\n4. 刷过要应用格式的文字\n\n> 考试常考：单击一次 vs 双击多次的区别。' WHERE id = 1179;

UPDATE knowledge_nodes SET content = '## 样式\n\n### 定义\n样式是**一组预定义的格式集合**（包含字体/字号/段落对齐/间距等），可一次性应用多种格式。\n\n### 内置样式\n| 样式 | 用途 |\n|------|------|\n| 正文 | 普通段落文字 |\n| 标题1~标题9 | 章节标题（标题1最高级别） |\n| 强调 | 重点文字 |\n\n### 样式的好处\n1. 格式统一：全文档标题/正文格式一致\n2. 快速排版：一键应用整套格式\n3. 自动生成目录：基于标题样式提取章节标题和页码\n4. 导航窗格：标题自动出现在导航窗格中，方便跳转\n\n> 考试重点：样式是目录自动生成的前提——必须先对标题应用标题样式。' WHERE id = 1180;

UPDATE knowledge_nodes SET content = '## 边框和底纹\n\n### 三类边框\n| 类型 | 应用范围 | 说明 |\n|------|------|------|\n| 字符边框 | 选中文字 | 给文字加外框 |\n| 段落边框 | 当前段落 | 给段落四周加框线 |\n| 页面边框 | 整个页面 | 给页面边缘加装饰边框（如花边） |\n\n### 底纹\n- 给文字或段落添加背景色或图案填充\n- 常用于突出标题或重要内容\n\n设置方法：开始→段落组→边框按钮→边框和底纹对话框' WHERE id = 1181;

UPDATE knowledge_nodes SET content = '## 页面格式\n\n| 设置项 | 说明 | 常用值 |\n|------|------|------|\n| 纸张大小 | 打印纸张的尺寸 | A4(210×297mm)/A3/16K/B5 |\n| 纸张方向 | 内容的排列方向 | 纵向（默认）/横向 |\n| 页边距 | 页面边缘到正文的距离 | 上下2.54cm/左右3.17cm（默认） |\n\n### 分栏\n将页面文字分为多栏显示（如两栏、三栏），常用于报纸/杂志排版。\n\n页面布局→页面设置组→纸张大小/方向/页边距/分栏\n\n> 实操常考：A4纸+纵向+上下2.5cm+左右3cm。' WHERE id = 1182;

UPDATE knowledge_nodes SET content = '## 页眉/页脚/页码\n\n### 页眉\n- 位于页面**顶部**，通常放文档标题/单位名称/Logo\n- 可设置首页不同（封面不要页眉）和奇偶页不同（书籍排版）\n\n### 页脚\n- 位于页面**底部**，通常放页码/日期/作者\n\n### 页码\n- 自动为每页生成序号\n- 格式可选：1,2,3... 或 I,II,III... 或 a,b,c...\n- 可设置起始页码\n\n> 实操常考：页眉"四川省XX学校"+页脚"第X页共Y页"。' WHERE id = 1183;

UPDATE knowledge_nodes SET content = '## 分页符/分节符/分栏符\n\n| 符号 | 快捷键 | 作用 |\n|------|------|------|\n| **分页符** | Ctrl+Enter | 强制从插入点开始新页（如每章另起一页） |\n| **分节符** | — | 将文档分为多个节，每节可独立设置页面格式（纸张方向/页眉页脚等） |\n| **分栏符** | — | 在多栏排版中强制文字从下一栏开始 |\n\n### 分节符的重要性\n- 同一文档中部分页面横向、部分纵向——靠分节符实现\n- 不同章节不同页眉——靠分节符+取消"链接到前一节"\n\n> 考点：分页符Ctrl+Enter是手动分页；分节符用于需要不同页面设置的场景。' WHERE id = 1184;

UPDATE knowledge_nodes SET content = '## 目录自动生成\n\n### 前提条件\n对文档中的章节标题应用了**标题样式**（标题1/标题2/标题3）。\n\n### 生成步骤\n1. 将光标定位到要插入目录的位置（通常是封面后第一页）\n2. 引用→目录→选择自动目录样式\n3. Word自动提取所有标题文字和页码生成目录\n\n### 更新目录\n修改文档后，右键目录→更新域→选择"更新整个目录"\n\n### 目录与导航窗格\n- 勾选 视图→导航窗格，可看到文档结构\n- 导航窗格中的标题来自标题样式\n\n> 考试重点：目录自动生成依赖于标题样式，不是手动输入的。' WHERE id = 1185;

-- ═══════════════════════════════════════════════════════════════
-- 单元1 > 任务3 使用表格 (1186-1189)
-- ═══════════════════════════════════════════════════════════════

UPDATE knowledge_nodes SET content = '## 表格的创建\n\n### 创建方法\n| 方法 | 操作 |\n|------|------|\n| 插入表格 | 插入→表格→拖动网格选择行列数 |\n| 插入表格对话框 | 插入→表格→插入表格→输入行列数 |\n| 绘制表格 | 插入→表格→绘制表格→鼠标自由绘制 |\n\n### 表格组成\n| 术语 | 说明 |\n|------|------|\n| 单元格 | 行和列的交叉点 |\n| 行 | 水平方向的一排单元格 |\n| 列 | 垂直方向的一排单元格 |\n\n> 实操常考：创建N行M列表格。' WHERE id = 1186;

UPDATE knowledge_nodes SET content = '## 表格操作\n\n| 操作 | 方法 |\n|------|------|\n| 插入行/列 | 右键→插入→在上方/下方插入行（或左/右插入列） |\n| 删除行/列 | 选中→右键→删除行/列 |\n| 合并单元格 | 选中多个单元格→右键→合并单元格 |\n| 拆分单元格 | 选中单元格→右键→拆分单元格→输入行列数 |\n| 调整行高列宽 | 拖动表格线/右键→表格属性 |\n\n> 实操重点：合并首行为标题行。' WHERE id = 1187;

UPDATE knowledge_nodes SET content = '## 表格属性\n\n| 属性 | 说明 |\n|------|------|\n| 行高 | 可设固定值或"最小值"（自动撑高） |\n| 列宽 | 可设固定值或百分比 |\n| 单元格对齐 | 水平（左中右）+ 垂直（上中下）= 9种对齐方式 |\n\n### 表格对齐\n- 表格整体：左对齐/居中/右对齐（相对于页面）\n- 单元格内容：右键→单元格对齐方式→选9种之一\n\n> 实操常考：单元格内容**水平居中+垂直居中**。' WHERE id = 1188;

UPDATE knowledge_nodes SET content = '## 表格边框/底纹/样式\n\n### 边框设置\n- 外边框和内部框线可**分别设置**粗细和线型\n- 常用"外粗内细"效果：外边框1.5磅实线+内部0.5磅虚线\n\n### 底纹\n- 给表头行添加灰色底纹以示区分\n\n### 表格样式\n- 设计→表格样式→选择预设样式\n- 自动包含边框/底纹/字体颜色搭配\n\n> 实操常考：表格"外粗内细"+表头加底纹。' WHERE id = 1189;

-- ═══════════════════════════════════════════════════════════════
-- 单元1 > 任务4 图文混排 (1190-1195)
-- ═══════════════════════════════════════════════════════════════

UPDATE knowledge_nodes SET content = '## 图片插入与文字环绕\n\n### 插入图片\n插入→图片→选择文件→图片出现在文档中\n\n### 文字环绕方式（5种）\n| 方式 | 效果 | 适用场景 |\n|------|------|------|\n| **嵌入型** | 图片像一个大字符，随文字移动 | 正式文档插图（默认） |\n| **四周型** | 文字环绕图片四周矩形边界 | 图文并茂文章 |\n| **紧密型** | 文字紧贴图片轮廓环绕 | 不规则形状图片 |\n| **浮于文字上方** | 图片盖在文字上面 | 水印/Logo叠加 |\n| **衬于文字下方** | 图片在文字下面 | 背景图/水印 |\n\n> 考试重点：5种环绕方式的名称和效果区分。嵌入型是最"规矩"的方式。' WHERE id = 1190;

UPDATE knowledge_nodes SET content = '## 形状(自选图形)\n\n插入→形状→选择矩形/圆形/箭头/星形等\n\n### 形状操作\n| 操作 | 方法 |\n|------|------|\n| 添加文字 | 右键→添加文字 |\n| 更改填充色 | 绘图工具→形状填充 |\n| 更改轮廓 | 绘图工具→形状轮廓 |\n| 旋转 | 拖动旋转手柄 |\n\n### 画布\n插入多个形状时可先插入画布（绘图画布），将所有形状放在画布内便于整体移动。' WHERE id = 1191;

UPDATE knowledge_nodes SET content = '## 艺术字\n\n艺术字是带有特殊视觉效果的**装饰性文字**（渐变/阴影/发光/三维旋转等）。\n\n### 插入方法\n插入→艺术字→选择样式→输入文字\n\n### 与普通文字的区别\n- 艺术字本质是"图形对象"，可像图片一样拖动和缩放\n- 普通文字需要通过字体设置来改变外观\n\n### 用途\n- 海报标题、宣传单、封面设计\n\n> 考试注意：艺术字是图形对象而非普通文字。' WHERE id = 1192;

UPDATE knowledge_nodes SET content = '## 文本框\n\n文本框是独立的文字容器，可自由定位在页面任意位置。\n\n| 类型 | 文字方向 | 适用场景 |\n|------|------|------|\n| 横排文本框 | 水平排列 | 常规标注、注释 |\n| 竖排文本框 | 垂直排列 | 古典风格排版、对联 |\n\n### 特点\n- 文本框内文字可独立设置格式\n- 文本框本身可设边框/填充色\n- 多个文本框可链接（文字溢出自动流入下一个文本框）\n\n> 文本框相当于在页面上放了一个"小文档"。' WHERE id = 1193;

UPDATE knowledge_nodes SET content = '## SmartArt图形\n\nSmartArt是Office内置的**信息可视化工具**，将文字转化为专业图表。\n\n### 常用类型\n| 类型 | 用途 | 示例 |\n|------|------|------|\n| 流程 | 显示步骤/阶段 | 操作步骤→→→ |\n| 层次结构 | 显示层级关系 | 组织架构图 |\n| 循环 | 显示循环往复过程 | PDCA循环 |\n| 关系 | 显示元素间关系 | 对比/平衡图 |\n\n### 操作\n插入→SmartArt→选择类型→输入文字→可随时更改颜色和样式\n\n> 实操常考：创建流程图或组织架构图。' WHERE id = 1194;

UPDATE knowledge_nodes SET content = '## 公式与图表\n\n### 公式编辑器\n插入→公式→选择内置公式或插入新公式\n- 内置公式：二次公式/二项式定理/傅里叶级数等\n- 自定义公式：使用公式工具栏输入分数/根号/积分/求和等结构\n\n### 图表\n插入→图表→选择类型（柱状图/折线图/饼图等）→自动打开Excel编辑数据\n- Word图表的数据源是嵌入的Excel工作表\n- 修改数据后图表自动更新\n\n> Word中图表功能与Excel相通，用于需要数据的图文报告。' WHERE id = 1195;

-- ═══════════════════════════════════════════════════════════════
-- 单元1 > 任务5 完善文档 (1196-1199)
-- ═══════════════════════════════════════════════════════════════

UPDATE knowledge_nodes SET content = '## 修订功能\n\n修订用于**跟踪文档的所有修改记录**，便于审阅者查看和决定是否接受。\n\n### 启用\n审阅→修订→切换为"开"状态\n\n### 修订内容\n| 操作 | 标记方式 |\n|------|------|\n| 插入文字 | 红色下划线 |\n| 删除文字 | 红色删除线（或批注框） |\n| 格式更改 | 批注框说明 |\n\n### 接受/拒绝\n- 审阅者可逐条"接受"或"拒绝"修订\n- 可一次性接受/拒绝全部修订\n\n> 修订常用于教师批改学生文档、编辑审稿等协作场景。' WHERE id = 1196;

UPDATE knowledge_nodes SET content = '## 批注\n\n批注是在文档中添加**评论或说明**而不直接修改正文。\n\n### 添加批注\n选中文字→审阅→新建批注→在批注框中输入评论\n\n### 批注 vs 修订\n| 对比 | 批注 | 修订 |\n|------|------|------|\n| 作用 | 提建议/问问题 | 直接修改 |\n| 影响正文 | 不影响 | 标记修改 |\n| 显示 | 侧边批注框 | 正文中标记 |\n\n> 批注相当于在文档旁边贴便利贴，修订相当于直接改原文。' WHERE id = 1197;

UPDATE knowledge_nodes SET content = '## 文档比较与合并\n\n### 比较\n审阅→比较→选择原文档和修订文档→Word自动生成对比结果\n- 显示两版文档的所有差异\n- 适合查看别人改了什么\n\n### 合并\n审阅→比较→合并→将多位审阅者的修订合并到同一文档中\n- 每个审阅者的修订以不同颜色显示\n\n> 比较用于查看差异，合并用于整合多人修改。' WHERE id = 1198;

UPDATE knowledge_nodes SET content = '## 脚注和尾注\n\n| 类型 | 位置 | 用途 |\n|------|------|------|\n| **脚注** | 当前页底部 | 对本页某个词语的即时解释 |\n| **尾注** | 文档末尾 | 参考文献、整体注释 |\n\n### 插入方法\n引用→插入脚注（或插入尾注）→输入注释文字\n\n### 编号\n自动编号，增删时自动重新排序\n\n> 脚注"即时看"在页底，尾注"最后看"在文末。' WHERE id = 1199;

-- ═══════════════════════════════════════════════════════════════
-- 单元1 > 任务6 邮件合并 (1200-1202)
-- ═══════════════════════════════════════════════════════════════

UPDATE knowledge_nodes SET content = '## 邮件合并\n\n邮件合并是Word的高级功能，用于**批量生成**内容相同但部分信息不同的大量文档。\n\n### 三要素\n| 要素 | 说明 | 示例 |\n|------|------|------|\n| **主文档** | 包含固定内容的Word文档 | 通知书模板（学校名称、正文固定） |\n| **数据源** | 包含可变信息的表格数据 | Excel学生名单（姓名/学号各不相同） |\n| **合并域** | 主文档中标记"此处插入数据源字段"的位置 | <<姓名>> <<学号>> |\n\n### 典型应用\n- 批量生成学生成绩通知书\n- 批量打印毕业证书\n- 批量制作邀请函/信封/标签\n\n> 考试重点：邮件合并=主文档+数据源→批量生成个性化文档。' WHERE id = 1200;

UPDATE knowledge_nodes SET content = '## 数据源类型\n\n邮件合并支持多种数据源：\n\n| 数据源 | 说明 |\n|------|------|\n| Excel表格 | **最常用**，每列一个字段，第一行为字段名 |\n| Access数据库 | Access表或查询结果 |\n| Outlook联系人 | 邮件地址簿 |\n| Word表格 | Word文档中的表格数据 |\n\n### Excel作为数据源的要求\n- 第一行为字段名（标题行）\n- 数据从第一列开始连续排列\n- 不要有空行空列\n\n> 常考：Excel是最常用的邮件合并数据源。' WHERE id = 1201;

UPDATE knowledge_nodes SET content = '## 合并域与完成合并\n\n### 操作步骤\n1. 准备Excel数据源（如学生名单.xlsx）\n2. 在Word中创建主文档模板\n3. 邮件→选择收件人→使用现有列表→选择Excel文件\n4. 插入合并域（在需要个性化内容的位置插入<<字段名>>）\n5. 预览结果→检查每条记录\n6. 完成合并→编辑单个文档（生成一个包含所有人的文档）或打印\n\n### 合并域示例\n```\n同学 <<姓名>>（学号：<<学号>>）：\n    你本学期期末考试成绩为 <<总分>> 分。\n```\n合并后每条记录自动替换<<姓名>>/<<学号>>/<<总分>>为实际值。\n\n> 实操必考流程：准备数据→选择收件人→插入合并域→完成合并。' WHERE id = 1202;

-- ═══════════════════════════════════════════════════════════════
-- 单元2 Excel > 任务1 采集数据 (1203-1209)
-- ═══════════════════════════════════════════════════════════════

UPDATE knowledge_nodes SET content = '## Excel 2010 工作界面\n\n| 区域 | 说明 |\n|------|------|\n| 名称栏（名称框） | 显示当前选中单元格的地址（如A1） |\n| 编辑栏 | 显示/编辑当前单元格的内容或公式 |\n| 列标 | A, B, C...（字母标识） |\n| 行号 | 1, 2, 3...（数字标识） |\n| 工作表标签 | Sheet1/Sheet2/Sheet3，可重命名和切换 |\n| 单元格 | 行和列的交叉点，地址=列标+行号（如A1/B5） |\n\n> 考点：单元格地址命名规则——列标+行号（字母在前，数字在后）。' WHERE id = 1203;

UPDATE knowledge_nodes SET content = '## 工作簿/工作表/单元格\n\n### 层级关系\n```\n工作簿 (.xlsx文件)\n  ├── 工作表1 (Sheet1)\n  │   ├── 单元格 A1\n  │   ├── 单元格 A2\n  │   └── ...\n  ├── 工作表2 (Sheet2)\n  └── 工作表3 (Sheet3)\n```\n\n| 概念 | 说明 | 类比 |\n|------|------|------|\n| 工作簿 | 一个Excel文件 | 一本账本 |\n| 工作表 | 工作簿中的一页 | 账本中的一页纸 |\n| 单元格 | 工作表中的一个格子 | 纸上的一个格子 |\n\n> 默认每个新工作簿有3个工作表。' WHERE id = 1204;

UPDATE knowledge_nodes SET content = '## 工作表操作\n\n| 操作 | 方法 |\n|------|------|\n| 新建 | 单击Sheet标签旁的"+"（插入工作表按钮） |\n| 删除 | 右键Sheet标签→删除 |\n| 重命名 | 双击Sheet标签→输入新名称 |\n| 复制/移动 | 右键→移动或复制→选择目标位置 |\n| 标签颜色 | 右键→工作表标签颜色→选择颜色 |\n\n### 行列操作\n| 操作 | 方法 |\n|------|------|\n| 插入行/列 | 右键→插入 |\n| 删除行/列 | 右键→删除 |\n| 行高列宽 | 拖动边界线/右键→行高/列宽 |\n| 隐藏 | 右键→隐藏 |\n| 取消隐藏 | 选中包含隐藏的行列→右键→取消隐藏 |\n\n> 工作表改名是最基本操作。' WHERE id = 1205;

UPDATE knowledge_nodes SET content = '## Excel视图\n\n| 视图 | 说明 | 用途 |\n|------|------|------|\n| **普通视图** | 默认视图，显示网格线 | 日常编辑 |\n| **分页预览** | 蓝色虚线显示分页位置，可拖动调整 | 调整打印分页 |\n| **页面布局视图** | 显示实际打印效果+页眉页脚 | 预览打印效果 |\n| 自定义视图 | 保存特定显示和打印设置 | 切换不同查看方案 |\n\n> 普通视图用于编辑，分页预览用于调整打印区域。' WHERE id = 1206;

UPDATE knowledge_nodes SET content = '## Excel数据类型\n\n| 类型 | 特征 | 默认对齐 | 示例 |\n|------|------|:--:|------|\n| **文本型** | 字母/数字/符号 | 左对齐 | 姓名、学号 |\n| **数值型** | 可参与计算 | 右对齐 | 85、3.14 |\n| **日期时间型** | yyyy-mm-dd格式 | 右对齐 | 2024-01-15 |\n| **货币型** | 自动加¥符号 | 右对齐 | ¥100.00 |\n| **百分比型** | 自动乘100加% | 右对齐 | 85% |\n\n### 文本型数字输入技巧\n- 身份证号/电话号码以单引号开头：在号码前加英文单引号使其强制为文本格式\n- 或先将单元格格式设为"文本"，再输入\n\n> 重点：身份证号必须按文本格式输入，否则会变成科学记数法并丢失末位。' WHERE id = 1207;

UPDATE knowledge_nodes SET content = '## 数据填充\n\n### 填充柄\n选中单元格，右下角出现**黑色十字**→拖拽即可填充\n\n### 填充类型\n| 操作 | 效果 | 示例 |\n|------|------|------|\n| 拖拽数值 | 复制相同值 | 1→1,1,1... |\n| Ctrl+拖拽数值 | 递增序列 | 1→1,2,3... |\n| 拖拽日期 | 按日递增 | 1月1日→1月2日,1月3日... |\n| 拖拽文本+数字 | 数字递增 | 第1组→第2组,第3组... |\n\n### 自定义序列\n文件→选项→高级→编辑自定义列表\n- 预设：星期一~星期日、一月~十二月\n- 可自定义：输入序列→添加→拖拽即按自定义顺序填充\n\n### 等差/等比序列\n开始→编辑→填充→序列→选择等差/等比/日期→设定步长值和终止值\n\n> 必考：填充柄是Excel最常用的效率工具。' WHERE id = 1208;

UPDATE knowledge_nodes SET content = '## 数据有效性\n\n数据有效性用于**限制单元格的输入内容**，防止输入错误数据。\n\n### 设置方法\n数据→数据工具→数据有效性→设置验证条件\n\n### 常用限制\n| 限制类型 | 示例 | 说明 |\n|------|------|------|\n| 整数范围 | 0~100 | 成绩不能超出范围 |\n| 序列（下拉列表） | 男,女 | 从列表中选择 |\n| 日期范围 | 2024-01-01~2024-12-31 | 限定日期区间 |\n| 文本长度 | 18位 | 身份证号固定长度 |\n| 自定义公式 | =COUNTIF(A:A,A1)=1 | 防止重复输入 |\n\n### 出错警告\n可设置输入无效数据时的提示信息（"请输入0-100之间的整数"）。\n\n> 实操重点：下拉列表（序列）和数据范围限制是最常用的有效性验证。' WHERE id = 1209;

-- ═══════════════════════════════════════════════════════════════
-- 单元2 > 任务2 修饰工作表 (1210-1214)
-- ═══════════════════════════════════════════════════════════════

UPDATE knowledge_nodes SET content = '## 单元格格式(Ctrl+1)\n\n选中单元格→Ctrl+1→设置单元格格式对话框，包含6个选项卡：\n\n| 选项卡 | 功能 | 常用操作 |\n|------|------|------|\n| 数字 | 设置数据格式 | 数值保留2位小数/货币¥/日期/文本/百分比 |\n| 对齐 | 文字对齐和方向 | 水平居中+垂直居中/合并单元格/自动换行/文字旋转 |\n| 字体 | 字体/字号/颜色 | 同Word字体设置 |\n| 边框 | 单元格边框线 | 外边框/内部框线/斜线表头 |\n| 填充 | 背景色和图案 | 表头灰色底纹/隔行变色 |\n| 保护 | 锁定/隐藏 | 配合工作表保护使用 |\n\n> Ctrl+1是Excel最常用的快捷键之一，必记。' WHERE id = 1210;

UPDATE knowledge_nodes SET content = '## 合并单元格与自动换行\n\n### 合并单元格\n- "合并后居中"：将多个单元格合为一个大单元格，内容居中\n- 常用于表格标题行（如标题横跨整个表格宽度）\n- 注意：合并后只有左上角单元格保留数据，其他单元格内容丢失\n\n### 自动换行\n- 当文字超过列宽时自动折行显示\n- 勾选后行高自动调整\n\n### 跨列居中 vs 合并居中\n- 跨列居中：视觉上居中但不合并单元格，不影响数据处理\n- 合并居中：真正合并单元格，可能影响排序/筛选/公式引用\n\n> 实操：标题行→选中→合并后居中。但数据表中尽量避免合并单元格。' WHERE id = 1211;

UPDATE knowledge_nodes SET content = '## 表格格式套用\n\n开始→套用表格格式→选择预设样式（自动包含边框/底纹/字体搭配）\n\n### 优点\n- 一键美化表格外观\n- 自动添加筛选按钮\n- 新增行/列自动继承格式\n- 支持隔行变色（斑马条纹）\n\n### 转换为区域\n套用表格格式后如需移除：设计→转换为区域\n\n> 套用表格格式 = 专业外观 + 自动功能。' WHERE id = 1212;

UPDATE knowledge_nodes SET content = '## 条件格式\n\n条件格式使符合条件的单元格**自动应用指定格式**，数据变化时格式自动更新。\n\n### 常用条件格式\n| 类型 | 功能 | 示例 |\n|------|------|------|\n| 突出显示规则 | 满足条件的单元格特殊标记 | 大于90分→绿色填充 |\n| 数据条 | 单元格内显示数据条长度 | 直观对比销售额大小 |\n| 色阶 | 按值大小显示不同颜色 | 高温→红色/低温→蓝色 |\n| 图标集 | 在数据旁显示图标(↑→↓/★/✓✗) | 成绩评级 |\n\n### 应用场景\n- 成绩表：<60分红色、≥90分绿色\n- 库存表：低于安全库存的用红色警告\n\n> 必考：条件格式是Excel智能化的代表功能——数据变、格式自动变。' WHERE id = 1213;

UPDATE knowledge_nodes SET content = '## 冻结窗格\n\n冻结窗格使某些行/列在滚动时**保持可见**。\n\n| 冻结方式 | 说明 | 适用 |\n|------|------|------|\n| 冻结首行 | 第1行始终可见 | 查看标题行 |\n| 冻结首列 | 第1列始终可见 | 查看行标签 |\n| 冻结拆分窗格 | 自由指定冻结位置 | 同时冻结行列 |\n\n### 操作\n视图→冻结窗格→选择冻结方式\n\n### 典型场景\n- 学生成绩表（冻结表头行+姓名列，滚动查看成绩时表头和姓名始终可见）\n\n> 实操常考：冻结首行+冻结首列。' WHERE id = 1214;

-- ═══════════════════════════════════════════════════════════════
-- 单元2 > 任务3 使用公式和函数 (1215-1227)
-- ═══════════════════════════════════════════════════════════════

UPDATE knowledge_nodes SET content = '## Excel公式构成\n\nExcel公式以 **`=`** 开头，由运算符和操作数组成。\n\n### 公式示例\n```\n=A1+B1           → A1的值加B1的值\n=SUM(A1:A10)     → A1到A10的和\n=B2*C2           → B2的值乘以C2的值\n```\n\n### 公式的组成部分\n| 部分 | 说明 | 示例 |\n|------|------|------|\n| `=` | 公式标志 | 必须以等号开头 |\n| 操作数 | 参与计算的值 | 数字/单元格引用/函数结果/文本 |\n| 运算符 | 计算符号 | + - * / ^ & |\n\n> 核心规则：Excel公式**必须**以等号开头，否则视为文本。' WHERE id = 1215;

UPDATE knowledge_nodes SET content = '## Excel运算符\n\n| 类别 | 运算符 | 说明 | 示例 |\n|------|------|------|------|\n| 算术 | + | 加 | =A1+B1 |\n| | - | 减 | =A1-B1 |\n| | * | 乘 | =A1*B1 |\n| | / | 除 | =A1/B1 |\n| | ^ | 乘方 | =A1^2 (A1的平方) |\n| 比较 | = | 等于 | =A1=B1 |\n| | > | 大于 | =A1>60 |\n| | < | 小于 | =A1<60 |\n| | >= | 大于等于 | =A1>=60 |\n| | <= | 小于等于 | =A1<=60 |\n| | <> | 不等于 | =A1<>B1 |\n| 文本 | & | 文本连接 | ="姓名："&A1 |\n| 引用 | : | 区域引用 | A1:B10 |\n| | , | 联合引用 | SUM(A1,A3,A5) |\n\n> 重点区分：=是赋值等于，==不存在于Excel中。比较运算符结果是TRUE或FALSE。' WHERE id = 1216;

UPDATE knowledge_nodes SET content = '## 单元格引用（必考核心）\n\n| 引用类型 | 写法 | 复制公式时 | 类比 |\n|------|------|------|------|\n| **相对引用** | A1 | 行列都变 | 相对位置 |\n| **绝对引用** | $A$1 | 行列都不变 | 固定位置 |\n| **混合引用** | $A1 | 列固定，行可变 | 列锁住 |\n| | A$1 | 行固定，列可变 | 行锁住 |\n\n### $符号的作用\n- `$` = "锁住"，加在谁前面谁就不变\n- `$A$1` 列和行都锁住 → 拖到哪都引用A1\n- F4键快速切换引用类型\n\n### 示例\n```\n在C1中: =A1*$B$1\n向下拖拽: C2 = A2*$B$1  (A1→A2相对变, $B$1保持不变)\n```\n\n> **考试必考！** 100%会出题：给一个公式和拖拽方向，问拖拽后新单元格的公式是什么。' WHERE id = 1217;

UPDATE knowledge_nodes SET content = '## SUM函数\n\n**功能**：计算指定区域所有数值的**总和**。\n\n### 语法\n```\n=SUM(数值1, 数值2, ...)\n=SUM(区域)\n```\n\n### 示例\n```\n=SUM(A1:A10)       → A1到A10的总和\n=SUM(A1,B1,C1)     → A1+B1+C1\n=SUM(A1:A10, 100)  → 区域和再加100\n```\n\n### 快速求和\nAlt+=（选中区域后按Alt+等号）→ 自动插入SUM公式\n\n> 最基础的函数，几乎所有表格都需要求和。' WHERE id = 1218;

UPDATE knowledge_nodes SET content = '## AVERAGE函数\n\n**功能**：计算指定区域数值的**算术平均值**。\n\n### 语法\n```\n=AVERAGE(区域)\n```\n\n### 示例\n```\n=AVERAGE(B2:B20)   → B2到B20的平均分\n```\n\n### 与手动计算的区别\n- 手动：`=(A1+A2+A3)/3` → 数据多时不便\n- AVERAGE自动忽略空白单元格和文本\n\n> 常与SUM配合：SUM求总分，AVERAGE求平均分。' WHERE id = 1219;

UPDATE knowledge_nodes SET content = '## MAX/MIN函数\n\n| 函数 | 功能 | 示例 |\n|------|------|------|\n| MAX | 返回最大值 | =MAX(B2:B20) → 最高分 |\n| MIN | 返回最小值 | =MIN(B2:B20) → 最低分 |\n\n### 典型应用\n- 学生成绩表：找最高分/最低分\n- 销售数据：找最大销售额/最小销售额\n\n> MAX和MIN常与条件格式配合——标出最好和最差。' WHERE id = 1220;

UPDATE knowledge_nodes SET content = '## COUNT系列函数\n\n| 函数 | 功能 | 计数对象 |\n|------|------|------|\n| COUNT | 数值计数 | 只统计**数值型**单元格 |\n| COUNTA | 非空计数 | 统计**非空**单元格（含文本） |\n| COUNTIF | 条件计数 | 统计**满足条件**的单元格 |\n\n### 示例\n```\n=COUNT(A1:A20)         → 数字个数\n=COUNTA(A1:A20)        → 有数据的单元格个数\n=COUNTIF(B2:B20,">=90") → 成绩≥90的人数\n=COUNTIF(C2:C20,"男")   → 男生人数\n```\n\n### COUNT vs COUNTA\n```\nA1=85, A2=缺考(文本), A3=92, A4=(空)\nCOUNT(A1:A4) = 2   (只数85和92)\nCOUNTA(A1:A4) = 3  (数85、缺考、92)\n```\n\n> 考试区分点：COUNT只数数字，COUNTA数所有非空。' WHERE id = 1221;

UPDATE knowledge_nodes SET content = '## IF函数\n\n**功能**：根据条件返回不同结果。\n\n### 语法\n```\n=IF(条件, 条件为TRUE时的值, 条件为FALSE时的值)\n```\n\n### 示例\n```\n=IF(B2>=90,"优秀",IF(B2>=80,"良好",IF(B2>=60,"及格","不及格")))\n```\n\n### 嵌套IF\nIF函数可以嵌套，Excel 2010最多嵌套64层。\n\n### 典型应用\n- 成绩等级：≥90优秀/≥80良好/≥60及格/<60不及格\n- 判断通过：≥60→"通过"，<60→"未通过"\n\n> 必考函数之一，成绩等级判断是最常见的考题。' WHERE id = 1222;

UPDATE knowledge_nodes SET content = '## SUMIF函数\n\n**功能**：对**满足条件的**单元格求和。\n\n### 语法\n```\n=SUMIF(条件区域, 条件, [求和区域])\n```\n\n### 示例\n```\n=SUMIF(C2:C20,"男",D2:D20)  → 所有男生的成绩总和\n=SUMIF(B2:B20,">=90")       → ≥90的成绩总和（求和区域=条件区域时可省略）\n```\n\n### SUMIF vs SUM+IF\nSUMIF一步完成"先筛选再求和"，比SUM+IF组合更简洁。\n\n> 条件求和是数据分析的基础操作。' WHERE id = 1223;

UPDATE knowledge_nodes SET content = '## VLOOKUP函数（高频考点）\n\n**功能**：在表格的**首列**查找指定值，返回该行**指定列**的值（垂直查找）。\n\n### 语法\n```\n=VLOOKUP(查找值, 表格区域, 返回第几列, 0)\n```\n第四个参数0表示精确匹配（几乎总是用0）。\n\n### 示例\n```\n=VLOOKUP(A2, 学生表!A:D, 2, 0)\n→ 在"学生表"的A列找A2的值，找到后返回该行第2列(姓名)\n```\n\n### 关键要求\n- 查找值必须在表格区域的**第一列**\n- 表格区域的第一列必须是查找依据列\n\n### 典型应用\n- 根据学号查找姓名/成绩\n- 根据商品编号查找价格\n\n> **必考函数！** 口诀：VLOOKUP(找谁, 在哪找, 返回第几列, 0)' WHERE id = 1224;

UPDATE knowledge_nodes SET content = '## RANK函数\n\n**功能**：返回某数值在一组数值中的**排名**。\n\n### 语法\n```\n=RANK(数值, 区域, [0降序/1升序])\n```\n- 0或省略：降序排名（越大排名越前，成绩排名用这个）\n- 1：升序排名（越小排名越前）\n\n### 示例\n```\n=RANK(B2,$B$2:$B$20,0)  → B2在B2:B20中的降序排名\n```\n注意：区域必须用**绝对引用**($B$2:$B$20)，否则拖拽时会偏移。\n\n### 注意\n相同值会得到**相同排名**（如并列第3名），但会跳过后续名次（下一个直接第5名）。\n\n> 成绩排名是RANK最经典的应用场景。' WHERE id = 1225;

UPDATE knowledge_nodes SET content = '## LEFT/MID/RIGHT文本函数\n\n| 函数 | 功能 | 语法 |\n|------|------|------|\n| LEFT | 从**左边**截取 | =LEFT(文本, 长度) |\n| MID | 从**中间**截取 | =MID(文本, 起始位置, 长度) |\n| RIGHT | 从**右边**截取 | =RIGHT(文本, 长度) |\n\n### 示例\n```\n=LEFT("计算机应用",3)   → "计算机"  (前3个字符)\n=MID("510101200001010001",7,8)  → "20000101" (第7位起取8位=提取出生日期)\n=RIGHT("计算机应用",2)  → "应用"    (后2个字符)\n```\n\n### 典型应用\n- 从身份证号中提取出生日期：=MID(身份证号,7,8)\n- 从学号中提取年级：=LEFT(学号,4)\n\n> 常与IF/VLOOKUP组合使用。' WHERE id = 1226;

UPDATE knowledge_nodes SET content = '## 日期与时间函数\n\n| 函数 | 功能 | 示例 |\n|------|------|------|\n| TODAY() | 返回当前日期 | 2024-01-15 |\n| NOW() | 返回当前日期和时间 | 2024-01-15 14:30 |\n| YEAR(日期) | 提取年份 | =YEAR(TODAY())→2024 |\n| MONTH(日期) | 提取月份 | =MONTH(TODAY())→1 |\n| DAY(日期) | 提取日 | =DAY(TODAY())→15 |\n\n### 特点\n- TODAY()和NOW()是**易变函数**，每次打开文件或计算时自动更新\n- YEAR/MONTH/DAY用于从日期中提取成分\n\n### 典型应用\n- 计算年龄：=YEAR(TODAY())-YEAR(出生日期)\n- 计算到期日：=日期+天数\n\n> TODAY()和NOW()无参数但括号不能省略。' WHERE id = 1227;

-- ═══════════════════════════════════════════════════════════════
-- 单元2 > 任务4 分析管理数据 (1228-1232)
-- ═══════════════════════════════════════════════════════════════

UPDATE knowledge_nodes SET content = '## 排序\n\n排序将数据按指定字段的升序或降序重新排列。\n\n### 单字段排序\n选中排序列中任一单元格→数据→升序/降序\n\n### 多字段排序\n数据→排序→添加条件：\n- 主要关键字：第一排序依据\n- 次要关键字：主关键字相同时的排序依据\n\n### 自定义排序\n按自定义序列排序（如按"优/良/中/差"顺序）\n\n> 考试点：多条件排序时，先按主要关键字排，相同的再按次要关键字排。' WHERE id = 1228;

UPDATE knowledge_nodes SET content = '## 筛选\n\n筛选**隐藏不满足条件的行**，只显示符合条件的记录。\n\n### 自动筛选\n数据→筛选→每列标题出现下拉箭头→勾选/取消勾选\n\n### 按条件筛选\n| 条件 | 示例 |\n|------|------|\n| 等于/不等于 | 班级="计算机1班" |\n| 大于/小于 | 成绩 > 80 |\n| 介于 | 成绩 60~80 |\n| 文本筛选 | 开头是"张" |\n\n### 高级筛选\n可设置复杂的多条件筛选（AND/OR组合），结果可复制到新位置。\n\n> 筛选与排序的区别：排序改变顺序，筛选隐藏行（数据仍在，只是不显示）。' WHERE id = 1229;

UPDATE knowledge_nodes SET content = '## 分类汇总\n\n分类汇总按**指定字段分组**计算统计值（求和/计数/平均值等）。\n\n### 前提\n必须**先按分类字段排序**！否则同类数据不在连续行中，汇总混乱。\n\n### 操作步骤\n1. 按分类字段排序（如按"班级"排序）\n2. 数据→分级显示→分类汇总\n3. 设置：分类字段=班级、汇总方式=平均值、汇总项=成绩\n\n### 结果\n- Excel插入汇总行（如"1班 平均值"、"2班 平均值"）\n- 左侧出现分级按钮(1/2/3)，可折叠展开\n\n> 必考点：分类汇总前**必须先排序**。这是最容易丢分的点。' WHERE id = 1230;

UPDATE knowledge_nodes SET content = '## 合并计算\n\n合并计算将**多个工作表或工作簿**中相同结构的数据汇总到一个表中。\n\n### 操作\n数据→数据工具→合并计算→选择函数(求和/平均值等)→添加引用区域\n\n### 应用场景\n- 汇总各班成绩到年级总表\n- 合并各月销售数据到年度总表\n\n> 合并计算用于跨表汇总，与分类汇总（同表分组）互补。' WHERE id = 1231;

UPDATE knowledge_nodes SET content = '## 数据透视表\n\n数据透视表是Excel最强大的**交互式数据汇总分析**工具。\n\n### 四大区域\n| 区域 | 作用 | 示例 |\n|------|------|------|\n| 行标签 | 按什么分组看 | 班级（每班一行） |\n| 列标签 | 按什么交叉看 | 科目（每科一列） |\n| 值 | 统计什么 | 成绩（求和/计数/平均） |\n| 报表筛选 | 按什么筛选 | 年级（只看2024级） |\n\n### 创建\n插入→数据透视表→选择数据源→拖拽字段到四个区域\n\n### 典型应用\n- 按班级统计各科平均分（行=班级，列=科目，值=平均成绩）\n\n> 数据透视表是数据分析进阶的必修课。' WHERE id = 1232;

-- ═══════════════════════════════════════════════════════════════
-- 单元2 > 任务5 制作图表 (1233-1236)
-- ═══════════════════════════════════════════════════════════════

UPDATE knowledge_nodes SET content = '## 图表组成\n\n| 组成部分 | 说明 |\n|------|------|\n| 图表区 | 整个图表的背景区域 |\n| 绘图区 | 实际绘制图形数据的区域 |\n| 数据系列 | 图表中的柱/线/扇区 |\n| 坐标轴 | X轴（分类轴）+ Y轴（数值轴） |\n| 图例 | 说明各数据系列的颜色和名称 |\n| 图表标题 | 图表的名称 |\n\n> 认识图表的6个基本组成部分。' WHERE id = 1233;

UPDATE knowledge_nodes SET content = '## 常用图表类型\n\n| 类型 | 用途 | 示例场景 |\n|------|------|------|\n| **柱形图** | 数据**对比** | 各班成绩对比 |\n| **折线图** | 数据**趋势** | 各月销售额趋势 |\n| **饼图** | 数据**占比** | 各科分值占比 |\n| **条形图** | 水平数据对比 | 排名展示 |\n\n### 选择原则\n- 比较大小 → 柱形图\n- 看变化趋势 → 折线图\n- 看各部分比例 → 饼图\n\n> 必考点：能根据场景选择合适的图表类型。' WHERE id = 1234;

UPDATE knowledge_nodes SET content = '## 图表操作\n\n| 操作 | 方法 |\n|------|------|\n| 创建 | 选中数据→插入→选择图表类型 |\n| 移动 | 拖拽图表/设计→移动图表→新工作表 |\n| 调整大小 | 拖拽图表角上的尺寸控点 |\n| 更改类型 | 右键→更改图表类型 |\n| 切换行列 | 设计→切换行/列 |\n\n### 快速创建\n选中数据→Alt+F1 → 在当前工作表创建默认图表\n\n> 创建图表前先选好数据区域。' WHERE id = 1235;

UPDATE knowledge_nodes SET content = '## 图表格式\n\n| 格式项 | 设置方法 |\n|------|------|\n| 图表样式 | 设计→图表样式→选择预设样式 |\n| 图表标题 | 单击标题→输入文字→设置字体 |\n| 坐标轴格式 | 右键坐标轴→设置坐标轴格式→刻度/数字格式 |\n| 数据标签 | 布局→数据标签→显示数值/百分比 |\n| 图例位置 | 布局→图例→底部/右侧/左侧/顶部 |\n\n### 数据标签的重要性\n- 柱形图添加数据标签可直接看到数值，无需对照Y轴\n- 饼图添加百分比标签更直观\n\n> 实操常考：添加图表标题和数据标签。' WHERE id = 1236;

