-- 单元2 > 任务6: 打印工作表 (1237-1240)
UPDATE knowledge_nodes SET content = '## 页面设置\n页面布局→页面设置：页边距、纸张方向(纵向/横向)、缩放比例(如将工作表缩放到一页宽)。' WHERE id = 1237;
UPDATE knowledge_nodes SET content = '## 打印标题\n页面布局→打印标题→设置**顶端标题行**(每页都打印表头)和**左端标题列**。' WHERE id = 1238;
UPDATE knowledge_nodes SET content = '## 分页符\n页面布局→分页符→插入分页符(强制分页)/删除分页符。分页预览视图中蓝色虚线即为自动分页位置。' WHERE id = 1239;
UPDATE knowledge_nodes SET content = '## 工作表保护\n审阅→保护工作表→设置密码→勾选允许的操作。可保护工作簿结构(防止增删工作表)或保护工作表(禁止编辑)。' WHERE id = 1240;

-- 单元3 PPT > 任务1: 创建演示文稿 (1241-1243)
UPDATE knowledge_nodes SET content = '## PPT 2010工作界面与视图\n| 视图 | 说明 |\n|------|------|\n| 普通视图 | 左侧缩略图+中间编辑区+下方备注(默认) |\n| 幻灯片浏览 | 全部幻灯片缩略图，方便排序 |\n| 阅读视图 | 窗口内放映 |\n| 幻灯片放映 | 全屏放映(F5从头/Shift+F5从当前) |\n> 默认视图是普通视图，包含幻灯片编辑区+大纲/缩略图+备注栏。' WHERE id = 1241;
UPDATE knowledge_nodes SET content = '## 演示文稿操作\n新建(Ctrl+N)/打开(Ctrl+O)/保存(Ctrl+S)/另存为(F12)。PPT默认格式为.pptx，兼容格式为.ppt。' WHERE id = 1242;
UPDATE knowledge_nodes SET content = '## 幻灯片操作\n| 操作 | 方法 |\n|------|------|\n| 新建幻灯片 | 开始→新建幻灯片→选版式 |\n| 复制幻灯片 | Ctrl+D 或右键→复制幻灯片 |\n| 移动幻灯片 | 在缩略图区拖拽 |\n| 删除幻灯片 | 选中→Delete |\n| 更改版式 | 右键→版式→选择新布局 |' WHERE id = 1243;

-- 单元3 PPT > 任务2: 幻灯片母版 (1244-1247)
UPDATE knowledge_nodes SET content = '## 幻灯片版式\n内置版式：标题幻灯片/标题和内容/两栏内容/比较/空白/仅标题等。新建幻灯片时选择合话的版式。' WHERE id = 1244;
UPDATE knowledge_nodes SET content = '## 幻灯片母版\n视图→幻灯片母版→设置统一字体/背景/Logo。母版修改后所有基于该母版的幻灯片自动更新。插入Logo到母版→每页都会出现。' WHERE id = 1245;
UPDATE knowledge_nodes SET content = '## 主题/模板\n设计→主题→选择预定义配色+字体组合。模板是包含内容和设计的完整演示文稿(.potx)。' WHERE id = 1246;
UPDATE knowledge_nodes SET content = '## 背景设置\n设计→背景样式→设置背景格式：纯色填充/渐变填充/图片或纹理填充。可"全部应用"或"重置背景"。' WHERE id = 1247;

-- 单元3 PPT > 任务3: 丰富内容 (1248-1253)
UPDATE knowledge_nodes SET content = '## 文字输入\n两种方式：占位符(点击虚线框直接输入)或文本框(插入→文本框→绘制文本框后输入)。字体段落设置与Word相同。' WHERE id = 1248;
UPDATE knowledge_nodes SET content = '## 图片/艺术字/形状\n插入→图片/艺术字/形状。操作与Word完全相同，选中后出现绘图工具格式选项卡可调整样式。' WHERE id = 1249;
UPDATE knowledge_nodes SET content = '## SmartArt/图表\n插入→SmartArt(流程/层次/循环/关系)或图表(柱/折/饼)。操作同Word和Excel。' WHERE id = 1250;
UPDATE knowledge_nodes SET content = '## 音频/视频\n插入→音频(文件中的音频)/视频(文件中的视频)→选择文件。支持MP3/WAV音频和MP4/WMV视频格式。' WHERE id = 1251;
UPDATE knowledge_nodes SET content = '## 超链接\n选中文字/图片→插入→超链接(Ctrl+K)→本文档中的位置/网页/其他文件/电子邮件地址。' WHERE id = 1252;
UPDATE knowledge_nodes SET content = '## 动作按钮\n插入→形状→动作按钮(前进/后退/首页/结束/帮助/信息)→绘制按钮→设置链接目标。常用于导航。' WHERE id = 1253;

-- 单元3 PPT > 任务4: 动画 (1254-1256)
UPDATE knowledge_nodes SET content = '## 动画类型\n| 类型 | 说明 | 示例 |\n|------|------|------|\n| 进入 | 对象出现的方式 | 飞入/淡出/擦除/浮入 |\n| 强调 | 对象在屏幕上的变化 | 放大/缩小/陀螺旋/变色 |\n| 退出 | 对象消失的方式 | 飞出/淡出/擦除 |\n| 动作路径 | 对象沿指定路径移动 | 直线/弧线/自定义路径 |\n> 一个对象可添加多个动画。动画→添加动画→选择类型。' WHERE id = 1254;
UPDATE knowledge_nodes SET content = '## 幻灯片切换\n切换→选择过渡效果(切出/淡出/推进/覆盖/揭开/溶解等)→设置持续时间。可"全部应用"到所有幻灯片。' WHERE id = 1255;
UPDATE knowledge_nodes SET content = '## 动画时序\n| 开始方式 | 说明 |\n|------|------|\n| 单击时 | 单击鼠标后播放动画 |\n| 与上一动画同时 | 两个动画同时播放 |\n| 上一动画之后 | 上一个播完后自动播放 |\n动画窗格可查看和调整所有动画的顺序和时序。' WHERE id = 1256;

-- 单元3 PPT > 任务5: 放映 (1257-1260)
UPDATE knowledge_nodes SET content = '## 放映方式\n| 操作 | 快捷键 |\n|------|------|\n| 从头开始 | F5 |\n| 从当前幻灯片开始 | Shift+F5 |\n放映中右键可切换指针/查看所有幻灯片/结束放映(Esc)。' WHERE id = 1257;
UPDATE knowledge_nodes SET content = '## 排练计时\n幻灯片放映→排练计时→按正常速度演讲→每页时间自动记录→保存后可自动按记录时间播放。' WHERE id = 1258;
UPDATE knowledge_nodes SET content = '## 自定义放映\n幻灯片放映→自定义放映→新建→勾选要放映的幻灯片子集。同一份PPT可为不同听众创建不同的放映版本。' WHERE id = 1259;
UPDATE knowledge_nodes SET content = '## 演示文稿打包\n文件→保存并发送→将演示文稿打包成CD→包含PPT文件+链接文件+字体+播放器。可在未安装PPT的电脑上播放。' WHERE id = 1260;

-- ═══════════════════════════════════════════════════════════════
-- Access 知识点 content (1270-1314)
-- ═══════════════════════════════════════════════════════════════

UPDATE knowledge_nodes SET content = '## 数据库核心概念\n| 术语 | 英文 | 说明 |\n|------|------|------|\n| 数据 | Data | 描述事物的符号记录 |\n| 数据库 | DB | 长期存储、有组织、可共享的数据集合 |\n| 数据库管理系统 | DBMS | 管理数据库的系统软件(Access/MySQL/Oracle) |\n| 数据库系统 | DBS | DB+DBMS+应用程序+DBA |\n\n### DBS = DB + DBMS + Application + DBA\n> 考试常考四者的包含关系：DBS包含DBMS，DBMS管理DB。' WHERE id = 1270;

UPDATE knowledge_nodes SET content = '## 数据库系统特点\n1. **数据结构化**：数据按数据模型组织\n2. **共享性高**：多用户可同时访问\n3. **独立性高**：数据与程序分离(逻辑独立+物理独立)\n4. **统一管理**：DBMS统一控制数据的安全性/完整性/并发\n\n> 独立性是数据库与文件系统的本质区别。' WHERE id = 1271;

UPDATE knowledge_nodes SET content = '## 数据模型三层次\n概念模型(信息世界)→逻辑模型(信息世界→机器世界桥梁)→物理模型(机器世界/存储层面)\n\n### 概念模型要点\n- ER图(实体-联系图)：矩形=实体，菱形=联系，椭圆=属性\n- 与具体DBMS无关，是用户与设计师交流的工具' WHERE id = 1272;

UPDATE knowledge_nodes SET content = '## 概念模型术语\n| 术语 | 说明 | 示例 |\n|------|------|------|\n| 实体 | 客观存在可区分的事物 | 一个学生、一门课 |\n| 属性 | 实体的特征 | 学号/姓名/年龄 |\n| 码(Key) | 唯一标识实体的属性 | 学号 |\n| 域 | 属性取值范围 | 性别域={男,女} |\n| 实体型 | 实体名+属性名 | 学生(学号,姓名,性别) |\n| 实体集 | 同类实体集合 | 全体学生 |' WHERE id = 1273;

UPDATE knowledge_nodes SET content = '## 实体间联系\n| 类型 | 说明 | 示例 |\n|------|------|------|\n| 一对一(1:1) | 一个A对应一个B | 班长↔班级 |\n| 一对多(1:n) | 一个A对应多个B | 班级↔学生 |\n| 多对多(m:n) | 多个A对应多个B | 学生↔课程(需中间表实现) |\n\n> 必考：能判断联系类型。1:n是最常见的关系。' WHERE id = 1274;

UPDATE knowledge_nodes SET content = '## 关系型数据库术语\n| 术语 | 说明 |\n|------|------|\n| 关系 | 一张二维表 |\n| 元组 | 表中的一行(记录) |\n| 属性 | 表中的一列(字段) |\n| 候选码 | 能唯一标识元组的属性或属性组 |\n| 主键 | 从候选码中选定的一个 |\n| 外键 | 本表的属性是另一表的主键 |\n\n### 关系的基本性质\n- 同一列数据类型相同\n- 行列次序可任意交换\n- 任意两行不能完全相同(必须有主键)' WHERE id = 1275;

UPDATE knowledge_nodes SET content = '## 三种关系运算\n| 运算 | 说明 | SQL对应 | 示例 |\n|------|------|------|------|\n| 选择 | 选取满足条件的**行** | WHERE | 选男生 |\n| 投影 | 选取指定的**列** | SELECT列名 | 只看姓名和成绩 |\n| 连接 | 两表按条件合成新关系 | JOIN | 学生表JOIN成绩表 |\n\n> 必考：选择=横向选行(WHERE)，投影=纵向选列(SELECT)，连接=两表合并(JOIN)。' WHERE id = 1276;

UPDATE knowledge_nodes SET content = '## Access六大对象\n| 对象 | 功能 | 核心程度 |\n|------|------|:--:|\n| 表 | 存储数据 | ⭐⭐⭐⭐⭐ |\n| 查询 | 检索计算数据 | ⭐⭐⭐⭐ |\n| 窗体 | 用户交互界面 | ⭐⭐⭐ |\n| 报表 | 格式化输出打印 | ⭐⭐⭐ |\n| 宏 | 自动化操作集合 | ⭐⭐ |\n| 模块 | VBA编程单元 | ⭐⭐ |\n\n> 所有数据都存在表中，其他对象都基于表。表是最核心的对象。' WHERE id = 1277;

UPDATE knowledge_nodes SET content = '## Access文件格式\n| 扩展名 | 版本 |\n|------|------|\n| .accdb | Access 2007及以后(默认) |\n| .mdb | Access 2003及以前 |\n\n.accdb支持更多新功能(多值字段/附件类型/计算字段等)。' WHERE id = 1278;

UPDATE knowledge_nodes SET content = '## 国产数据库\n信创背景下需了解的国产数据库：\n| 数据库 | 厂商 | 特点 |\n|------|------|------|\n| 达梦DM | 武汉达梦 | 国产老牌，兼容Oracle |\n| 人大金仓KingbaseES | 人大金仓 | 基于PostgreSQL，政务常用 |\n| 南大通用GBase | 南大通用 | 分析型数据库强 |\n| OceanBase | 蚂蚁集团 | 分布式，金融级 |\n\n> 考纲只要求"了解"，知道2-3个名称即可。' WHERE id = 1279;

UPDATE knowledge_nodes SET content = '## Access常用数据类型\n| 类型 | 用途 | 最多 | 示例 |\n|------|------|------|------|\n| 文本 | 短文本 | 255字符 | 姓名 |\n| 备注 | 长文本 | 65535字符 | 简介 |\n| 数字 | 数值 | — | 成绩(含字节/整型/长整型/单双精度) |\n| 日期/时间 | 日期时间 | — | 出生日期 |\n| 货币 | 金额 | — | 工资(自动加¥) |\n| 自动编号 | 自增ID | — | 主键 |\n| 是/否 | 布尔 | — | 是否毕业 |\n| OLE对象 | 外部对象 | 1GB | 照片 |\n| 超链接 | 链接地址 | — | 网址 |\n| 附件 | 多文件 | 2GB | 简历附件 |\n\n> 必考：学号用文本，成绩用数字，出生日期用日期/时间。' WHERE id = 1280;

UPDATE knowledge_nodes SET content = '## 创建数据表方法\n| 方法 | 说明 | 推荐度 |\n|------|------|:--:|\n| 数据表视图 | 直接输入数据，字段自动识别 | ⭐⭐ |\n| 设计视图 | 先定义字段名/类型/属性(专业) | ⭐⭐⭐⭐⭐ |\n| 表模板 | 使用内置模板 | ⭐ |\n\n> 推荐用设计视图建表——先定义结构再输入数据。' WHERE id = 1281;

UPDATE knowledge_nodes SET content = '## 修改表结构\n设计视图中：添加/删除字段、修改数据类型、调整字段顺序(拖拽)。\n注意：已有数据的字段改类型可能导致数据丢失！' WHERE id = 1282;

UPDATE knowledge_nodes SET content = '## 数据库运算符\n| 类别 | 运算符 |\n|------|------|\n| 算术 | + - * / \\\\ (整除) Mod (取模) ^ |\n| 关系 | = > < >= <= <> |\n| 逻辑 | AND OR NOT |\n| 字符 | & (连接) |\n| 特殊 | BETWEEN...AND / IN / LIKE / IS NULL |\n\n### LIKE通配符\n- `*` 匹配任意字符 → LIKE "王*" 匹配所有姓王的\n- `?` 匹配单个字符 → LIKE "王?" 匹配"王二"不匹配"王小明"' WHERE id = 1283;

UPDATE knowledge_nodes SET content = '## 特殊运算符\n| 运算符 | 含义 | 示例 |\n|------|------|------|\n| BETWEEN...AND | 在范围内 | [成绩] BETWEEN 60 AND 80 |\n| IN(...) | 在列表中 | [班级] IN("1班","2班") |\n| LIKE | 模糊匹配 | [姓名] LIKE "张*" |\n| IS NULL | 为空 | [电话] IS NULL |\n| IS NOT NULL | 不为空 | [电话] IS NOT NULL |\n\n> LIKE的*通配符和IS NULL的语法是高频考点。' WHERE id = 1284;

UPDATE knowledge_nodes SET content = '## 字段大小\n文本型：限制最多字符数(默认255)。\n数字型：字节(0-255)/整型(-32768~32767)/长整型/单精度/双精度——选择合适的范围以节省存储。' WHERE id = 1285;

UPDATE knowledge_nodes SET content = '## 格式属性\n控制数据的显示方式(不改变实际存储值)。\n如日期格式：yyyy-mm-dd → 2024-01-15\n数字格式：0.00 → 始终显示2位小数' WHERE id = 1286;

UPDATE knowledge_nodes SET content = '## 输入掩码\n限制输入格式，防止错误输入。\n| 掩码字符 | 含义 |\n|------|------|\n| 0 | 必须输入数字(0-9) |\n| 9 | 可选数字 |\n| A | 必须输入字母或数字 |\n| L | 必须输入字母 |\n身份证掩码示例：000000-00000000-000A' WHERE id = 1287;

UPDATE knowledge_nodes SET content = '## 默认值与有效性规则\n### 默认值\n新建记录时自动填入的值(性别默认"男")。\n\n### 有效性规则\n限制输入范围：\n- `[成绩]>=0 AND [成绩]<=100` → 成绩必须0~100\n- `[性别]="男" OR [性别]="女"` → 性别只能填男或女\n\n### 有效性文本\n违反规则时弹出的提示信息(如"成绩必须介于0到100之间")。' WHERE id = 1288;

UPDATE knowledge_nodes SET content = '## 其他字段属性\n| 属性 | 说明 |\n|------|------|\n| 必填字段 | 是否允许为空(是/否) |\n| 允许零长度字符串 | 是否允许""(注意区分Null) |\n| 索引 | 有重复/无重复(唯一索引) |\n| 标题 | 数据表视图的列标题(代替字段名) |\n\n> Null vs 空字符串：Null=没有值，""=有空字符串值。两者不等价。' WHERE id = 1289;

UPDATE knowledge_nodes SET content = '## 记录浏览与定位\n数据表视图中底部有导航按钮：第一条/前一条/后一条/最后一条/新增记录\n快捷方式：Tab→下一个字段, Shift+Tab→上一个字段' WHERE id = 1290;

UPDATE knowledge_nodes SET content = '## 记录编辑\n修改：直接编辑单元格。撤消：Esc键(放弃当前字段修改)。删除：选中行→Delete键→确认。注意删除后不可撤消。' WHERE id = 1291;

UPDATE knowledge_nodes SET content = '## 数据表格式设置\n行高列宽调整、冻结列(右键→冻结字段)、隐藏列(右键→隐藏字段)、字体/字号/颜色、网格线样式。这些设置不影响数据。' WHERE id = 1292;

UPDATE knowledge_nodes SET content = '## 数据排序\n单击字段→开始→升序/降序。多字段排序：先排次要字段，再排主要字段。Access排序只需点按钮无需像Excel那样选区域。' WHERE id = 1293;

UPDATE knowledge_nodes SET content = '## 数据筛选\n| 方式 | 说明 |\n|------|------|\n| 按选定内容筛选 | 选中值→右键→按选定筛选 |\n| 按窗体筛选 | 在空白窗体中输入筛选条件 |\n| 高级筛选 | 复杂多条件组合 |\n移除筛选：开始→排序和筛选→取消筛选。' WHERE id = 1294;

UPDATE knowledge_nodes SET content = '## 查找替换与导入导出\n查找：Ctrl+F→输入查找内容。替换：Ctrl+H→查找→替换为。\n数据导入导出：外部数据→Excel/Access(导入)或导出→Excel/文本文件。' WHERE id = 1295;

UPDATE knowledge_nodes SET content = '## 主键(Primary Key)\n唯一标识表中每条记录的字段：值不可重复、不可为空。\n创建：设计视图→选中字段→设计→主键按钮(钥匙图标)。\n最佳选择：自动编号字段——自动递增永不重复。' WHERE id = 1296;

UPDATE knowledge_nodes SET content = '## 索引(Index)\n加速数据检索，类似书的目录。\n| 类型 | 值 | 说明 |\n|------|------|------|\n| 有重复 | 允许重复值 | 普通字段 |\n| 无重复 | 唯一值 | 唯一索引(类似主键约束) |\n注意：索引太多会降低增删改的速度。主键自动创建唯一索引。' WHERE id = 1297;

UPDATE knowledge_nodes SET content = '## 表间关系类型\n| 关系 | 说明 | Access实现 |\n|------|------|------|\n| 一对一(1:1) | 主表主键=从表主键 | 较少用 |\n| 一对多(1:n) | 主表主键=从表外键 | 最常用 |\n| 多对多(m:n) | 需通过中间表(第三个表)连接 | 两对1:n |\n创建关系前提：主表有主键，从表有匹配字段。' WHERE id = 1298;

UPDATE knowledge_nodes SET content = '## 参照完整性\n保证相关表数据一致性：\n| 规则 | 说明 |\n|------|------|\n| 级联更新 | 主表主键更新→从表外键自动更新 |\n| 级联删除 | 主表记录删除→从表相关记录自动删除 |\n\n> 设置参照完整性后，不能删除被引用的主表记录(除非设了级联删除)。' WHERE id = 1299;

UPDATE knowledge_nodes SET content = '## 连接类型\n| 类型 | 结果 |\n|------|------|\n| 内部连接(默认) | 只含两表匹配的记录 |\n| 左外部连接 | 含左表所有记录(右表无匹配显示空) |\n| 右外部连接 | 含右表所有记录(左表无匹配显示空) |' WHERE id = 1300;

UPDATE knowledge_nodes SET content = '## 查询五大类型\n| 类型 | 说明 |\n|------|------|\n| 选择查询 | 按条件检索数据(最常用) |\n| 参数查询 | 运行时提示输入条件值 |\n| 交叉表查询 | 行列交叉汇总(类似透视表) |\n| 操作查询 | 批量修改数据(更新/删除/追加/生成表) |\n| SQL查询 | 直接编写SQL语句 |' WHERE id = 1301;

UPDATE knowledge_nodes SET content = '## 创建查询方法\n1. 查询向导：按引导创建\n2. 设计视图(QBE网格)：拖拽字段到网格(最常用)\n3. SQL视图：直接写SQL语句\n\n> QBE(Query By Example)网格是可视化的查询设计工具。' WHERE id = 1302;

UPDATE knowledge_nodes SET content = '## 查询条件设置\nQBE网格中：同一行的条件=AND关系(同时满足)，不同行的条件=OR关系(满足其一)。例：性别="男" AND 成绩>80 写在同行；两个不同条件写在不同行。' WHERE id = 1303;

UPDATE knowledge_nodes SET content = '## 计算字段\n在查询中创建表达式字段：`总分: [语文]+[数学]+[英语]`\n冒号前为字段名，冒号后为表达式。计算字段的值来自表数据，不存储在数据库中。' WHERE id = 1304;

UPDATE knowledge_nodes SET content = '## 分组统计\n设计视图→总计(Σ按钮)→Group By(分组)/Sum(求和)/Avg(平均)/Count(计数)/Max(最大)/Min(最小)\n例：按班级分组→对成绩字段选Avg→得到每班平均分。' WHERE id = 1305;

UPDATE knowledge_nodes SET content = '## 操作查询(更新/删除/追加/生成表)\n| 类型 | 作用 |\n|------|------|\n| 更新查询 | 批量修改数据 |\n| 删除查询 | 批量删除记录 |\n| 追加查询 | 批量添加记录到另一表 |\n| 生成表查询 | 查询结果生成新表 |\n\n> 操作查询会改变数据！执行前建议先备份。' WHERE id = 1306;
UPDATE knowledge_nodes SET content = '## 删除查询\n批量删除符合条件的记录。DELETE FROM 表 WHERE 条件。注意删除后无法撤消。' WHERE id = 1307;
UPDATE knowledge_nodes SET content = '## 追加查询\n将查询结果(若干条记录)添加到另一个表中。常用于数据归档和合并。' WHERE id = 1308;
UPDATE knowledge_nodes SET content = '## 生成表查询\n把查询结果保存为一个新表。适用于制作报表数据快照。' WHERE id = 1309;

UPDATE knowledge_nodes SET content = '## SELECT查询语句\n```sql\nSELECT [DISTINCT] 字段列表\nFROM 表名\n[WHERE 条件]\n[GROUP BY 分组字段 [HAVING 条件]]\n[ORDER BY 字段 [ASC|DESC]];\n```\n| 子句 | 作用 |\n|------|------|\n| SELECT | 选择哪些列(投影) |\n| FROM | 从哪个表 |\n| WHERE | 筛选哪些行(选择) |\n| ORDER BY | 排序(ASC升/DESC降) |\n\n> HAVING vs WHERE：WHERE筛选行，HAVING筛选分组后的结果。' WHERE id = 1310;

UPDATE knowledge_nodes SET content = '## CREATE TABLE语句\n```sql\nCREATE TABLE 表名 (\n  字段1 类型 [约束],\n  字段2 类型 [约束],\n  PRIMARY KEY (字段)\n);\n```\n| 约束 | 说明 |\n|------|------|\n| PRIMARY KEY | 主键 |\n| NOT NULL | 不允许空值 |\n| UNIQUE | 唯一约束 |' WHERE id = 1311;

UPDATE knowledge_nodes SET content = '## INSERT INTO语句\n```sql\nINSERT INTO 表名 (字段1,字段2) VALUES (值1,值2);\nINSERT INTO 表名 VALUES (值1,值2,...); -- 全部字段\n```\n注意：值与字段必须一一对应(数量/类型/顺序)。自动编号字段不需要插入值。' WHERE id = 1312;

UPDATE knowledge_nodes SET content = '## UPDATE语句\n```sql\nUPDATE 表名 SET 字段1=值1, 字段2=值2 WHERE 条件;\n```\n> 必须加WHERE！不加WHERE会更新全表所有记录(这是最常见的SQL事故)。' WHERE id = 1313;

UPDATE knowledge_nodes SET content = '## DELETE语句\n```sql\nDELETE FROM 表名 WHERE 条件;\n```\n> 同样必须加WHERE！不加WHERE删除全表所有记录。执行前务必检查条件。' WHERE id = 1314;

SELECT '=== Content填充完成(办公+Access) ===' AS '';
SELECT subject_id, COUNT(*) AS filled FROM knowledge_nodes WHERE subject_id IN (6,17) AND content IS NOT NULL AND content != '' GROUP BY subject_id;
